// src/pages/Selections.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import Card from "../components/common/Card";
import * as SelectionData from "../constants/selection";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Selections.module.css";

import eveVideo from "../assets/eve_sdm_talk.mp4";

const Selections = () => {
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [selectedId, setSelectedId] = useState(null);

  // 1. 關鍵：清空 HeroData，直接隱藏外層 Layout 的預設 Avatar 與標題
  // src/pages/Selections.jsx
  useEffect(() => {
    // 直接設為 null 隱藏外層大頭貼
    setHeroData(null);

    const welcomeText = `${allAnswers.userName || "您"}您好，我可以幫您什麼呢？請根據您想了解的問題選擇。`;
    handlePlaySpeech(welcomeText);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [setHeroData, allAnswers.userName]);

  // 🔊 語音與影片同步控制
  const handlePlaySpeech = (text) => {
    if (!window.speechSynthesis || !videoRef.current) return;

    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = "zh-TW";
    utterance.rate = 1.0;

    utterance.onstart = () => {
      setIsPlaying(true);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.muted = true;
        videoRef.current.play().catch((err) => console.log(err));
      }
    };

    utterance.onend = () => {
      setIsPlaying(false);
      setIsPaused(false);
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0;
      }
    };

    window.speechSynthesis.speak(utterance);
  };

  // ⏸️ 暫停 / 恢復切換核心邏輯
  const handleTogglePlay = (e) => {
    e.stopPropagation(); // 防止觸發外層點擊

    if (!window.speechSynthesis) return;

    if (isPlaying && !isPaused) {
      // 執行暫停
      window.speechSynthesis.pause();
      if (videoRef.current) videoRef.current.pause();
      setIsPaused(true);
    } else if (isPlaying && isPaused) {
      // 恢復播放
      window.speechSynthesis.resume();
      if (videoRef.current)
        videoRef.current.play().catch((err) => console.log(err));
      setIsPaused(false);
    } else {
      // 重新開始
      const welcomeText = `${allAnswers.userName || "您"}您好，我可以幫您什麼呢？請根據您想了解的問題選擇。`;
      handlePlaySpeech(welcomeText);
    }
  };

  const handleConfirm = () => {
    if (!selectedId) return alert("請先選擇一個方案");
    if (window.speechSynthesis) window.speechSynthesis.cancel();

    const paths = { 1: "/SDM", 2: "/chatbot" };
    const targetPath = paths[selectedId];
    if (targetPath) navigate(targetPath);
  };

  const currentSelection = SelectionData.selectionList.find(
    (s) => s.id === selectedId,
  );

  return (
    <div className={styles.pageContainer}>
      <div className={styles.interactiveCard}>
        {/* 頂部影片區 */}
        <div className={styles.videoSection}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            webkit-playsinline="true"
            preload="auto"
            loop
            className={styles.theatreVideo}
          />

          {/* 狀態標籤 */}
          {isPlaying && (
            <div className={styles.audioBadge}>
              <span
                className={isPaused ? styles.audioDotPaused : styles.audioDot}
              ></span>
              {isPaused ? "已暫停引言" : "小幫手引導中..."}
            </div>
          )}

          {/* 右下角動態播放/暫停按鈕 */}
          <button className={styles.controlBtn} onClick={handleTogglePlay}>
            {isPlaying && !isPaused ? "⏸ 暫停說明" : "▶️ 播放說明"}
          </button>
        </div>

        {/* 下半部選項區 */}
        <div className={styles.contentSection}>
          <div className={styles.cardList}>
            {SelectionData.selectionList.map((item) => (
              <Card
                key={item.id}
                title={item.title}
                description={item.description}
                isActive={selectedId === item.id}
                onClick={() => setSelectedId(item.id)}
              />
            ))}
          </div>

          <div className={styles.buttonGroup}>
            <Button onClick={handleConfirm} fullWidth>
              {selectedId
                ? `進入 ${currentSelection?.title} ➔`
                : "請選擇上方方案"}
            </Button>
            <Button variant="outline" onClick={() => navigate("/")} fullWidth>
              返回修改基本資料
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Selections;
